// Prepare Technical Analysis Prompt
const signal = $input.item.json.body.signal;

const prompt = `Analyze this crypto trading signal for ${signal.coin}USDT with deep technical analysis reasoning.

Signal Details:
- Direction: ${signal.direction}
- Entry Price: ${signal.entry}
- Stop Loss: ${signal.stoploss}
- Take Profit Targets: ${signal.targets.join(', ')}
- Leverage: ${signal.leverage}x

Please analyze:
1. Support and resistance levels around the entry point
2. Risk/Reward ratio calculation
3. Momentum indicators and trend strength
4. Volume analysis and market structure
5. Key technical patterns

Based on your deep technical analysis, determine if this trade setup is BULLISH or BEARISH.

Respond in this exact format:
VERDICT: [BULLISH or BEARISH]
REASONING: [Your comprehensive technical analysis in 3-4 sentences]`;

return {
  json: {
    signal: signal,
    prompt: prompt,
    analysisType: 'technical'
  }
};

// Prepare Risk Analysis Prompt
const signal = $input.item.json.signal;

const prompt = `Evaluate this ${signal.coin}USDT ${signal.direction} trade from a comprehensive risk management perspective.

Trade Parameters:
- Entry: ${signal.entry}
- Stop Loss: ${signal.stoploss}
- Targets: ${signal.targets.join(', ')}
- Leverage: ${signal.leverage}x

Analyze the following risk factors:
1. Position sizing and leverage appropriateness
2. Stop loss placement and invalidation levels
3. Take profit targets realism
4. Market volatility and liquidity conditions
5. Overall risk/reward assessment

Determine if the risk profile makes this trade BULLISH or BEARISH.

Respond in this exact format:
VERDICT: [BULLISH or BEARISH]
REASONING: [Your detailed risk assessment in 3-4 sentences]`;

return {
  json: {
    signal: signal,
    prompt: prompt,
    analysisType: 'risk',
    technicalAnalysis: $input.item.json.message.content
  }
};

// Prepare Sentiment Analysis Prompt
const signal = $input.item.json.signal;

const prompt = `Provide final validation for ${signal.coin}USDT ${signal.direction} trade based on market sentiment and broader context.

Consider:
1. Overall crypto market sentiment and Bitcoin correlation
2. News, events, or catalysts affecting ${signal.coin}
3. Funding rates and open interest trends
4. Whale activity and smart money flows
5. Social sentiment and fear/greed index

Based on comprehensive market sentiment analysis, is this setup BULLISH or BEARISH?

Respond in this exact format:
VERDICT: [BULLISH or BEARISH]
REASONING: [Your market sentiment analysis in 3-4 sentences]`;

return {
  json: {
    signal: signal,
    prompt: prompt,
    analysisType: 'sentiment',
    technicalAnalysis: $input.item.json.technicalAnalysis,
    riskAnalysis: $input.item.json.message.content
  }
};

// Calculate Consensus
const technical = $input.item.json.technicalAnalysis;
const risk = $input.item.json.riskAnalysis;
const sentiment = $input.item.json.message.content;

const analyses = [technical, risk, sentiment];

// Count verdicts
let bullishCount = 0;
let bearishCount = 0;

analyses.forEach(analysis => {
  const upper = analysis.toUpperCase();
  if (upper.includes('VERDICT: BULLISH')) {
    bullishCount++;
  } else if (upper.includes('VERDICT: BEARISH')) {
    bearishCount++;
  } else {
    // Fallback: check for keywords
    if (upper.includes('BULLISH')) bullishCount++;
    if (upper.includes('BEARISH')) bearishCount++;
  }
});

const verdict = bullishCount > bearishCount ? 'BULLISH' : 'BEARISH';
const signal = $input.item.json.signal;
const trendAligned = 
  (verdict === 'BULLISH' && signal.direction === 'LONG') ||
  (verdict === 'BEARISH' && signal.direction === 'SHORT');

// Calculate confidence
const total = bullishCount + bearishCount;
let confidence = 'Low';
if (total > 0) {
  const majority = Math.max(bullishCount, bearishCount);
  if (majority === total) {
    confidence = 'High';
  } else if (majority >= total * 0.66) {
    confidence = 'Medium';
  }
}

return {
  json: {
    signal: signal,
    aiVerdict: verdict,
    trendAligned: trendAligned,
    bullishVotes: bullishCount,
    bearishVotes: bearishCount,
    consensus: `${bullishCount} BULLISH vs ${bearishCount} BEARISH`,
    confidence: confidence,
    analysis1: technical.substring(0, 200),
    analysis2: risk.substring(0, 200),
    analysis3: sentiment.substring(0, 200),
    timestamp: new Date().toISOString()
  }
};
